(* 1. is_leap year: divisible by 4, except centuries not divisible by 400. *)
let is_leap y = (y mod 4 = 0 && y mod 100 <> 0) || y mod 400 = 0

(* 2. sum_digits n: the sum of the decimal digits of a non-negative integer. *)
let rec sum_digits n = if n < 10 then n else (n mod 10) + sum_digits (n / 10)

(* 3. gcd by Euclid's algorithm. *)
let rec gcd a b = if b = 0 then a else gcd b (a mod b)

(* 4. power b e in O(log e) multiplications, by repeated squaring. *)
let rec power b e =
  if e = 0 then 1
  else
    let half = power b (e / 2) in
    if e mod 2 = 0 then half * half else half * half * b

(* 5. collatz_length n: how many steps until n reaches 1. *)
let collatz_length n =
  let rec go n steps = if n = 1 then steps else go (if n mod 2 = 0 then n / 2 else (3 * n) + 1) (steps + 1) in
  go n 0

let () =
