(* 1. product and concat as folds. *)
let product = List.fold_left ( * ) 1
let concat ls = List.fold_right ( @ ) ls []

(* 2. unzip a list of pairs with one fold. *)
let unzip l = List.fold_right (fun (a, b) (xs, ys) -> (a :: xs, b :: ys)) l ([], [])

(* 3. apply a function n times. *)
let rec repeat n f x = if n = 0 then x else repeat (n - 1) f (f x)

(* 4. count_if and partition by hand. *)
let count_if p l = List.fold_left (fun n x -> if p x then n + 1 else n) 0 l

(* 5. group consecutive elements that satisfy an equivalence. *)
let group_by eq l =
  List.fold_right
    (fun x groups -> match groups with (y :: _ as g) :: rest when eq x y -> (x :: g) :: rest | _ -> [ x ] :: groups)
    l []

(* 6. compose a list of functions, applied left to right. *)
let pipeline fs x = List.fold_left (fun acc f -> f acc) x fs

