(* 1. a counter factory using a closure over a ref. *)
let make_counter () = let n = ref 0 in fun () -> incr n; !n

(* 2. reverse an array in place. *)
let reverse a =
  let n = Array.length a in
  for i = 0 to (n / 2) - 1 do
    let t = a.(i) in
    a.(i) <- a.(n - 1 - i);
    a.(n - 1 - i) <- t
  done

(* 3. bubble sort in place. *)
let bubble_sort a =
  let n = Array.length a in
  for pass = 0 to n - 2 do
    for i = 0 to n - 2 - pass do
      if a.(i) > a.(i + 1) then (let t = a.(i) in a.(i) <- a.(i + 1); a.(i + 1) <- t)
    done
  done

