(* 1. chain fallible steps with an option monad. *)
let ( let* ) = Option.bind
let safe_div a b = if b = 0 then None else Some (a / b)

let compute a b c =
  let* x = safe_div a b in
  let* y = safe_div x c in
  Some (x + y)

(* 2. a tiny logging monad: a value together with messages. *)
let return x = (x, [])
let bind (x, log) f = let y, log' = f x in (y, log @ log')
let step name f x = (f x, [ name ])

(* 3. sequencing events on a virtual clock. *)
let events : (int * string) list ref = ref []
let at time name = events := (time, name) :: !events
let run () = List.map snd (List.sort compare !events)

let () =
  let show = function Some n -> string_of_int n | None -> "none" in
  Printf.printf "%s %s\n" (show (compute 100 5 2)) (show (compute 100 0 2));
  let result, log = bind (bind (return 3) (step "double" (fun x -> x * 2))) (step "inc" (fun x -> x + 1)) in
  Printf.printf "%d %s\n" result (String.concat ">" log);
  at 30 "c"; at 10 "a"; at 20 "b";
  print_endline (String.concat "" (run ()))

(** [median l] requires a non-empty list and returns the middle element of the sorted list
    (the lower middle for an even length). *)
let median l =
  assert (l <> []);
  List.nth (List.sort compare l) ((List.length l - 1) / 2)

(** [insert_sorted x l] requires [l] sorted and returns a sorted list with [x] added. *)
let rec insert_sorted x = function [] -> [ x ] | y :: rest as l -> if x <= y then x :: l else y :: insert_sorted x rest

let rec sorted = function a :: (b :: _ as rest) -> a <= b && sorted rest | _ -> true

