(* 1. a queue from two stacks (lists). *)
type 'a queue = { inbox : 'a list; outbox : 'a list }

let push x q = { q with inbox = x :: q.inbox }

let pop q =
  match q.outbox with
  | x :: rest -> Some (x, { q with outbox = rest })
  | [] -> (match List.rev q.inbox with [] -> None | x :: rest -> Some (x, { inbox = []; outbox = rest }))

(* 2. binary search tree: insert, mem and in-order traversal. *)
type tree = Leaf | Node of tree * int * tree

let rec insert x = function
  | Leaf -> Node (Leaf, x, Leaf)
  | Node (l, v, r) as t -> if x < v then Node (insert x l, v, r) else if x > v then Node (l, v, insert x r) else t

let rec mem x = function Leaf -> false | Node (l, v, r) -> if x < v then mem x l else if x > v then mem x r else true
let rec inorder = function Leaf -> [] | Node (l, v, r) -> inorder l @ [ v ] @ inorder r
let rec height = function Leaf -> 0 | Node (l, _, r) -> 1 + max (height l) (height r)

(* 3. the smallest k elements using a sorted insertion buffer. *)
let smallest k l =
  let insert_k acc x = List.filteri (fun i _ -> i < k) (List.sort compare (x :: acc)) in
  List.fold_left insert_k [] l

